const e = $('Entree').first().json;
const s = $('Session').first().json;
const fin = t => [{ json: { etape: 'fin', resultat: t } }];
const h1 = String($('Recherche exacte').first().json.html || '');
const h2 = String($input.first().json.html || '');
if (/timed out/i.test(h1 + h2)) return fin('Session du portail pieces Daikin expiree pendant la recherche. Reessayer dans un instant.');
const parse = t => [...t.matchAll(/'unitName'\s*:\s*'([^']*)'[\s\S]*?'bookNo'\s*:\s*'([^']*)'[\s\S]*?'unitInfo'\s*:\s*'([^']*)'[\s\S]*?'factory'\s*:\s*'([^']*)'[\s\S]*?'bookFolder'\s*:\s*'([^']*)'/g)].map(m => ({ u: m[1], b: m[2], info: m[3], fab: m[4], f: m[5] })).filter(r => r.u !== 'UnitName');
const cle = x => String(x).toUpperCase().replace(/[^A-Z0-9]/g, '');
const ex = parse(h1), lg = parse(h2);
let c = ex.filter(r => cle(r.u) === e.modele);
if (!c.length) c = ex;
if (!c.length) c = lg.filter(r => e.modele.startsWith(cle(r.u)));
if (!c.length) c = lg;
if (!c.length) return fin('Modele ' + e.modele + ' introuvable sur le portail pieces Daikin. Verifier la plaque (unite interieure ou groupe exterieur) et recopier le modele complet.');
const eu = c.filter(r => r.fab === 'DENV');
const pick = (eu.length ? eu : c)[0];
const autres = c.filter(r => r !== pick).slice(0, 6).map(r => r.u);
return [{ json: { etape: 'liste', unite: pick.u, book: pick.b, folder: pick.f, exact: cle(pick.u) === e.modele, autres } }];

const i = $input.first().json || {};
const ref = String(i.reference || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const modele = String(i.modele || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const m = /^([A-Z]+\d+[A-Z]?)/.exec(modele);
return [{ json: { ref, modele, prefixe: m ? m[1] : modele, mots_cles: String(i.mots_cles || '').slice(0, 200), role: String(i.role || 'technicien').toLowerCase() } }];

const e = $('Entree').first().json;
const x = String($input.first().json.xml || '');
const tag = (b, t) => { const m = new RegExp('<' + t + '>([\\s\\S]*?)</' + t + '>').exec(b); return m ? m[1].replace(/&amp;/g, '&').trim() : ''; };
const rows = [];
const vus = new Set();
for (const m of x.matchAll(/<parts>([\s\S]*?)<\/parts>/g)) {
  const b = m[1];
  const pn = tag(b, 'pn');
  if (!/^[0-9A-Z]{5,}$/.test(pn) || vus.has(pn)) continue;
  vus.add(pn);
  rows.push({ pn, des: tag(b, 'Name'), repere: tag(b, 'loc'), spec: tag(b, 'Spec'), note: tag(b, 'Note') });
}
if (!rows.length) return [{ json: { etape: 'liste_complete', vide: true, lignes: [] } }];
const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const syn = [
  [/VENTIL|MOTEUR VENT/, ['FAN MOTOR', 'MOTOR FAN', 'DC FAN MOTOR']],
  [/HELICE|TURBINE/, ['PROPELLER FAN', 'CROSS FLOW FAN', 'FAN ROTOR', 'TURBO FAN']],
  [/CARTE|ELECTRONIQUE|PCB|PWB|PLATINE/, ['PCB ASSY', 'PCB', 'PRINTED CIRCUIT', 'P.C.B']],
  [/COMPRESS/, ['COMPRESSOR']],
  [/SONDE|CAPTEUR|THERMISTANCE/, ['THERMISTOR', 'SENSOR']],
  [/4 VOIES|VANNE 4|INVERSION/, ['FOUR WAY', '4 WAY', '4-WAY', 'REVERSING']],
  [/DETENDEUR|EXPANSION/, ['MOTOR OPERATED VALVE', 'EXPANSION VALVE', 'ELECTRONIC EXPANSION', 'COIL']],
  [/CONDENSATEUR/, ['CAPACITOR']],
  [/TELECOMMANDE/, ['REMOTE CONTROLLER', 'REMOTE CONTROL', 'WIRELESS REMOTE']],
  [/POMPE/, ['DRAIN PUMP', 'PUMP']],
  [/VOLET|SWING/, ['STEPPING MOTOR', 'SWING MOTOR', 'SWING FLAP', 'BLADE', 'FLAP']],
  [/PRESSOSTAT/, ['PRESSURE SWITCH', 'HIGH PRESSURE SWITCH']],
  [/CAPTEUR PRESSION/, ['PRESSURE SENSOR']],
  [/FLOTTEUR/, ['FLOAT SWITCH']],
  [/FILTRE/, ['AIR FILTER', 'FILTER']],
  [/BAC/, ['DRAIN PAN']],
  [/FUSIBLE/, ['FUSE']],
  [/BATTERIE|ECHANGEUR|EVAPORATEUR/, ['HEAT EXCHANGER', 'COIL']],
  [/BORNIER/, ['TERMINAL STRIP', 'TERMINAL BLOCK']],
  [/SELF|REACTANCE/, ['REACTOR']]
];
const demande = norm(e.mots_cles);
const kws = new Set(demande.split(/[,;\/]+/).map(s => s.trim()).filter(s => s.length >= 3));
for (const [r, l] of syn) if (r.test(demande)) l.forEach(k => kws.add(k));
const cands = rows.map(r => { const d = norm(r.des); let s = 0; for (const k of kws) if (d.includes(k)) s += k.length; return { r, s }; }).filter(o => o.s > 0).sort((a, b) => b.s - a.s).slice(0, 3).map(o => o.r);
if (!cands.length) return [{ json: { etape: 'liste_complete', lignes: rows.map(r => 'rep ' + r.repere + ' | ' + r.pn + ' | ' + r.des + (r.spec ? ' ' + r.spec : '')) } }];
return cands.map(c => ({ json: Object.assign({ etape: 'detail' }, c) }));

function tous(n) { try { return $(n).all().map(i => i.json); } catch (x) { return null; } }
function un(n) { try { return $(n).first().json; } catch (x) { return null; } }
const e = $('Entree').first().json;
const admin = e.role === 'admin';
const MARGE = 1.30;
const fmt = n => n.toFixed(2).replace('.', ',') + ' EUR';
const s = un('Session') || {};
if (s.etape === 'fin') return [{ json: { resultat: s.resultat } }];
const ch = un('Choix modele');
if (ch && ch.etape === 'fin') return [{ json: { resultat: ch.resultat } }];
const pc = tous('Pieces');
const L = [];
if (ch && ch.unite) {
  L.push('Modele Daikin ' + ch.unite + (ch.exact ? '' : ' (le plus proche de ' + e.modele + ')') + '.');
  if (ch.autres && ch.autres.length) L.push('Autres variantes : ' + ch.autres.join(', ') + '. Si la plaque indique une autre variante, les pieces peuvent differer.');
}
if (pc && pc[0] && pc[0].etape === 'liste_complete') {
  if (pc[0].vide) L.push('Vue eclatee introuvable pour ce modele sur le portail Daikin.');
  else {
    L.push('Aucune piece ne correspond a : ' + e.mots_cles + '. Liste des pieces du modele (repere | reference | designation) :');
    pc[0].lignes.slice(0, 120).forEach(l => L.push(l));
    L.push('Choisis la bonne ligne et rappelle l outil avec sa reference exacte.');
  }
  return [{ json: { resultat: L.join('\n') } }];
}
const cands = (pc && pc[0] && pc[0].etape === 'detail') ? pc : [s];
const det = $input.all().map(i => String((i.json || {}).html || ''));
const TR = { 'available': 'disponible', 'available in low quantity': 'disponible, petite quantite', 'available in very low quantity': 'disponible, tres petite quantite', 'available in average quantity': 'disponible, quantite moyenne', '(to be confirmed)': 'a confirmer' };
const tr = v => TR[String(v || '').toLowerCase().trim()] || String(v || '').trim() || 'inconnu';
const prix = v => { const m = /([\d.,]+)/.exec(String(v || '')); if (!m) return null; const n = parseFloat(m[1].replace(/,/g, '')); return isNaN(n) || n <= 0 ? null : n; };
const rowRe = /\{\s*"pn"\s*:\s*"([^"]*)"\s*,\s*"name"\s*:\s*"([^"]*)"[\s\S]*?"ListPrice0"\s*:\s*"([^"]*)"\s*,\s*"Stc0"\s*:\s*"([^"]*)"\s*,\s*"_qty0"\s*:\s*(-?\d+)\s*,\s*"Stc1"\s*:\s*"([^"]*)"\s*,\s*"_qty1"\s*:\s*(-?\d+)[\s\S]*?"stockType"\s*:\s*"(\w+)"/g;
let dateStock = '';
L.push(cands.length > 1 ? 'Pieces correspondantes :' : 'Piece Daikin :');
cands.forEach((c, i) => {
  const h = det[i] || '';
  if (/timed out/i.test(h) || !h) { L.push('- ' + (c.des || c.pn) + ' : ' + c.pn + '. Detail illisible sur le portail.'); return; }
  const rows = [...h.matchAll(rowRe)].map(m => ({ pn: m[1], name: m[2], prix: prix(m[3]), s0: m[4], q0: +m[5], s1: m[6], q1: +m[7], type: m[8] }));
  const d = /"label"\s*:\s*"France"\s*,\s*"date"\s*:\s*"(\d+)-(\d+)-(\d+)/.exec(h);
  if (d && !dateStock) dateStock = String(d[3]).padStart(2, '0') + '/' + String(d[2]).padStart(2, '0') + '/' + d[1];
  const o = rows.find(r => r.type === 'original');
  if (!o) { L.push('- Reference ' + c.pn + ' introuvable sur le portail pieces Daikin.'); return; }
  const sub = rows.find(r => r.type === 'substitute');
  const eff = sub || o;
  let l = '- ' + (c.des || o.name) + (c.repere ? ' (repere ' + c.repere + ')' : '') + ' : ' + o.pn + '.';
  if (sub) l += ' Remplacee par ' + sub.pn + ' (' + sub.name + ').';
  l += ' Stock Daikin France : ' + tr(eff.s1) + (eff.q1 > 0 ? ' (' + eff.q1 + ')' : '') + ' ; Belgique : ' + tr(eff.s0) + (eff.q0 > 0 ? ' (' + eff.q0 + ')' : '') + '.';
  if (eff.prix) {
    l += ' Prix indicatif client ' + fmt(Math.round(eff.prix * MARGE * 100) / 100) + ' HT hors pose.';
    if (admin) l += ' Prix catalogue Daikin (a afficher a Laurent) ' + fmt(eff.prix) + '.';
  } else l += ' Prix non communique : a demander au distributeur.';
  L.push(l);
});
const test = /spb-dev/.test(s.base || '');
L.push('Attention : stock Daikin' + (dateStock ? ' arrete au ' + dateStock : '') + (test ? ' (portail de test Daikin, stock probablement ancien)' : '') + ', a confirmer avec le distributeur avant de commander.');
L.push('Source : Daikin Spare Parts Bank, consulte le ' + $now.setZone('Europe/Paris').toFormat('dd/MM/yyyy') + '.');
return [{ json: { resultat: L.join('\n') } }];

const a = $('Lire acces').first().json || {};
const e = $('Entree').first().json;
const r = $input.first().json || {};
const base = String(a.url_base || 'https://www.spb-dev.daikin.co.jp').replace(/\/+$/, '');
const fin = t => [{ json: { etape: 'fin', resultat: t } }];
if (!a.mot_de_passe) return fin('Acces au portail pieces Daikin non configure (mot de passe absent de la Data Table daikin_spb_acces). Pour Daikin, applique la regle Demande de prix.');
const h = r.headers || {};
let sc = h['set-cookie'] || [];
if (!Array.isArray(sc)) sc = [sc];
const cookie = sc.map(c => String(c).split(';')[0]).filter(Boolean).join('; ');
const loc = String(h.location || '');
const body = String(r.body || r.data || '');
const echec = !cookie || /login\.asp/i.test(loc) || (/name="F_Pass"/i.test(body) && !/spbank/i.test(loc));
if (echec) return fin('Connexion au portail pieces Daikin impossible (identifiants refuses ou portail indisponible). Pour Daikin, applique la regle Demande de prix.');
if (e.ref) return [{ json: { etape: 'detail', base, cookie, pn: e.ref, des: '', repere: '' } }];
if (!e.modele) return fin('Ni reference de piece ni modele de machine : demander une photo de la plaque signaletique.');
return [{ json: { etape: 'modele', base, cookie } }];
